func (c *context) Scheme() string {
	// Can't use `r.Request.URL.Scheme`
	// See: https://groups.google.com/forum/#!topic/golang-nuts/pMUkBlQBDF0
	if c.IsTLS() {
		return "https"
	}
	if scheme := c.schemeFromHeader(HeaderXForwardedProto); scheme != "" {
		return scheme
	}
	if scheme := c.schemeFromHeader(HeaderXForwardedProtocol); scheme != "" {
		return scheme
	}
	if ssl := c.request.Header.Get(HeaderXForwardedSsl); ssl == "on" {
		return "https"
	}
	if scheme := c.schemeFromHeader(HeaderXUrlScheme); scheme != "" {
		return scheme
	}
	return "http"
}

// schemeFromHeader returns the value of the given header if it holds a valid
// HTTP protocol scheme (`http` or `https`), otherwise it returns an empty string.
func (c *context) schemeFromHeader(name string) string {
	scheme := c.request.Header.Get(name)
	if strings.EqualFold(scheme, "http") || strings.EqualFold(scheme, "https") {
		return strings.ToLower(scheme)
	}
	return ""
}

