	"net/http/httptest"
	"testing"
)

func TestZZUnmatchedPath(t *testing.T) {
	e := New()
	e.GET("/users/:id", func(c Context) error { return c.String(200, c.Path()) })
	var got string
	e.HTTPErrorHandler = func(err error, c Context) {
		got = c.Path()
		c.NoContent(404)
	}
	req := httptest.NewRequest(http.MethodGet, "/does-not-exist", nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	fmt.Println("unmatched path:", fmt.Sprintf("%q", got), "code:", rec.Code)
	if got != "" {
		t.Fatalf("expected empty path, got %q", got)
	}
	// matched still works
	rec = httptest.NewRecorder()
	e.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/users/1", nil))
	if rec.Body.String() != "/users/:id" {
		t.Fatalf("matched path wrong: %q", rec.Body.String())
	}
}

func TestZZScheme(t *testing.T) {
	e := New()
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	c := e.NewContext(req, httptest.NewRecorder())
	req.Header.Set("X-Forwarded-Proto", "ftp")
	req.Header.Set("X-Url-Scheme", "https")
	fmt.Println("scheme:", c.Scheme())
	if c.Scheme() != "https" {
		t.Fatal("expected https")
	}
	req.Header.Del("X-Url-Scheme")
	fmt.Println("scheme (only bogus):", c.Scheme())
	if c.Scheme() != "http" {
		t.Fatal("expected http")
	}
	req.Header.Set("X-Forwarded-Proto", "HTTPS")
	fmt.Println("scheme (upper):", c.Scheme())
}
EOF
