// Support binding to limited Map destinations:
// - map[string][]string,
// - map[string]string <-- (binds first value from data slice)
// - map[string]interface{}
// You are better off binding to struct as this package has limited reflection support.
if typ.Kind() == reflect.Map {
	if typ.Key().Kind() != reflect.String {
		return errors.New("only map[string]T is supported")
	}
	if val.IsNil() {
		val.Set(reflect.MakeMap(typ))
	}
	switch typ.Elem().Kind() {
	case reflect.Slice:
		for k, v := range data {
			slice := reflect.MakeSlice(typ.Elem(), len(v), len(v))
			for i := range v {
				if err := setWithProperType(typ.Elem().Elem().Kind(), v[i], slice.Index(i)); err != nil {
					return err
				}
			}
			val.SetMapIndex(reflect.ValueOf(k), slice)
		}
	case reflect.String:
		for k, v := range data {
			val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v[0]))
		}
	case reflect.Interface:
		for k, v := range data {
			val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v))
		}
	default:
		return errors.New("unsupported map type")
	}
	return nil
}

